import heapq


def _round(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _ledger(data, sequence_first, discounted_base):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (seq, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted_base else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]
                           if row["version"] not in blocked.get(name, [])
                           and (name not in pins or row["version"] == pins[name])})
        choices.append([-1] + versions)

    best = None
    best_vector = None
    rows_by_version = {
        name: {row["version"]: row for row in packages[name]} for name in names
    }
    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version != -1}
        graph = {name: [] for name in selected}
        valid = True
        for name, (low, high) in roots.items():
            version = selected.get(name)
            if version is None or not low <= version <= high:
                valid = False
                break
        if not valid:
            continue

        for name, version in selected.items():
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target)
                if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Only packages reachable by following active dependencies from roots belong.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != set(selected):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in selected):
            continue

        vector = tuple(values)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best = selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked:
        return {"error": "impossible"}
    available = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (source, initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


